import{z as s,x as i,o as t,c as A,q as o,j as n,D as e,d as l,s as c,S as E}from"./chunks/framework.C8m1ZpeB.js";const L=JSON.parse('{"title":"cuBLAS / cuDNN 边界","description":"","frontmatter":{"title":"cuBLAS / cuDNN 边界","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/cublas-cudnn.md","filePath":"llm/cublas-cudnn.md","lastUpdated":1791063341000}'),u={name:"llm/cublas-cudnn.md"};function d(p,a,B,m,N,D){const r=i("Mermaid");return t(),A("div",null,[a[2]||(a[2]=o('<h1 id="cublas-cudnn-边界" tabindex="-1">cuBLAS / cuDNN 边界 <a class="header-anchor" href="#cublas-cudnn-边界" aria-label="Permalink to &quot;cuBLAS / cuDNN 边界&quot;">​</a></h1><div class="epigraph"><p>cuBLAS 回答的是「这块矩阵乘用哪条 GEMM 路径」；cuDNN 回答的是「这段网络原语——卷积、归一化、融合注意力——用哪条 DNN 路径」。二者都吃 Tensor Core，但合同与融合边界不同。</p><footer>—— NVIDIA cuBLAS / cuBLASLt 与 cuDNN 开发者指南，对照 CUDA 与架构白皮书</footer></div><p>框架把 Transformer 降成算子之后，真正打在 GPU 上的往往不是用户写的 <code>matmul</code>，而是两套厂商库。线性层、MLP 的宽矩阵乘走 cuBLAS / cuBLASLt；卷积时代留下的归一化、softmax、以及后来的融合 SDPA / FMHA 走 cuDNN。混用是常态：同一层里 QKV 投影可能是 Ltmatmul，注意力是 cuDNN 或 FlashAttention，输出投影又回到 Lt。分清边界，是为了知道问题该去哪张 release note 里找，以及何时该放弃库、换成 <a href="/llm/cutlass">CUTLASS</a> 或手写核。</p><p>本篇写 API 合同、启发式、融合能做什么不能做什么。不引用未公开的内部选核表。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>BLAS 的对象是向量与矩阵：<code>GEMM</code>、\\(C \\leftarrow \\alpha AB+\\beta C\\)，加上 batched、strided batched。cuBLASLt 把布局、数据类型、可选 epilogue（bias、ReLU、GELU、DReLU 等）收进一次 matmul 描述符，让启发式在「同一数学对象」下选不同 kernel。DNN 库的对象是层：卷积算法空间、归一化的训练/推理模式、注意力的掩码与尺度、RNN 的序列包。把注意力当成两次 GEMM 去调 cuBLAS，softmax 仍是第三方核，中间分数要落 HBM——这正是 <a href="/llm/kernel-fusion-tiling">融合</a> 要避免的。cuDNN 的融合注意力把「两次乘 + softmax + 掩码」收成一个算法条目，合同是层，不是 BLAS。</p><p>边界模糊的区域存在。LayerNorm / RMSNorm 两边都可能出现；softmax 作为 BLAS 扩展和作为 DNN 原语都有；Transformer Engine 又在二者之上做 FP8 缩放。问题不是「选一个库用到底」，而是「这个张量变换的数学对象是 GEMM 还是层，融合是否必须跨过 softmax 或归一化归约」。</p><p><span class="marginnote">epilogue（收尾段）就是矩阵乘算完主体后「顺手做的小活」：加上 bias、过一道 ReLU 或 GELU。库把它并入同一次 kernel 发射，省得为几行小计算再单独排队起一个核——小核的启动开销常比计算本身还贵。</span></p><h3 id="启发式不是算法保证" tabindex="-1">启发式不是算法保证 <a class="header-anchor" href="#启发式不是算法保证" aria-label="Permalink to &quot;启发式不是算法保证&quot;">​</a></h3><p><code>cublasLtMatmul</code> 与 <code>cudnnFind*</code> / 运行时选计划，都按形状、对齐、步幅、GPU 型号在一组预编译核里挑。同一 \\((M,N,K)\\) 在对齐 16 与对齐 1 时可能完全不同；decode 的 \\(M=1\\) 可能选到通用核而不是 Tensor Core 大 tile。换驱动或换 cuDNN 小版本，计划可能变，墙钟与数值尾差都可能变。把它当成确定性算法会在回归测试里踩坑：要钉版本，或钉计划缓存。</p><p><span class="marginnote">Lt 的 epilogue 能融 bias 和一部分激活，融不了 RMSNorm 那种跨最后一维的完整归约，也融不了带在线统计的注意力。看到「fused matmul」不要推断已经做了 FlashAttention 级的 IO 优化。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对 LLM 前向，一条可操作的分工是：</p><ul><li><strong>密集线性、MLP 门控、嵌入后的投影</strong>：cuBLASLt。保证 K 维对齐、dtype 落在该代 Tensor Core 支持集，让启发式能选 MMA 核。需要 bias+激活且 Lt 支持该组合时，走 epilogue，避免再写一个点核。</li><li><strong>卷积 / 早期视觉塔、部分归一化、厂商融合注意力</strong>：cuDNN。PyTorch 的 <code>scaled_dot_product_attention</code> 在若干版本上可以后端到 cuDNN FMHA；是否真走，要看形状、头维、掩码类型和开关。与 FlashAttention 的对照应在目标形状上测，见 <a href="/llm/flashattention-3">FA3</a> 对厂商核的说明。</li><li><strong>库覆盖不住的</strong>：分页 KV、投机树、自定义掩码、分组 GEMM 与 MoE 的不规则专家——CUTLASS、Triton 或自写。不要指望 cuBLAS 的 batched GEMM 在专家大小差一个数量级时仍接近峰值。</li></ul><p><span class="marginnote">直觉类比：cuBLAS 像「只管矩阵乘的专家柜台」，单据（描述符）极简，随到随算；cuDNN 像「搭标准网络层的一站式柜台」，要填 pad、掩码、序列长度一大份表格，第一次排队久（选计划），但整层一起做。自己手写核则像自己开小作坊，什么都能做但什么都得自己保。</span></p>',15)),(t(),n(E,null,{default:e(()=>[c(r,{id:"mermaid-57",class:"mermaid",graph:"flowchart%20TD%0A%20%20OP%5B%22%E6%A1%86%E6%9E%B6%E7%AE%97%E5%AD%90%22%5D%20--%3E%20Q%7B%22%E6%95%B0%E5%AD%A6%E5%AF%B9%E8%B1%A1%22%7D%0A%20%20Q%20--%3E%7C%22GEMM%20%2F%20%E6%9C%89%E9%99%90%20epilogue%22%7C%20LT%5B%22cuBLASLt%22%5D%0A%20%20Q%20--%3E%7C%22%E5%B1%82%EF%BC%9A%E6%B3%A8%E6%84%8F%E5%8A%9B%20%2F%20conv%20%2F%20%E9%83%A8%E5%88%86%20norm%22%7C%20DN%5B%22cuDNN%22%5D%0A%20%20Q%20--%3E%7C%22%E4%B8%8D%E8%A7%84%E5%88%99%20%2F%20%E5%88%86%E9%A1%B5%20%2F%20%E6%96%B0%E8%9E%8D%E5%90%88%22%7C%20HW%5B%22CUTLASS%20%2F%20%E6%89%8B%E5%86%99%22%5D%0A%20%20LT%20--%3E%20TC%5B%22Tensor%20Core%22%5D%0A%20%20DN%20--%3E%20TC%0A%20%20HW%20--%3E%20TC%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o('<h3 id="fp8-与-transformer-engine" tabindex="-1">FP8 与 Transformer Engine <a class="header-anchor" href="#fp8-与-transformer-engine" aria-label="Permalink to &quot;FP8 与 Transformer Engine&quot;">​</a></h3><p>Hopper 起的 FP8 训练/推理不是「cuBLAS 换个 dtype」那么简单。缩放因子、amax 延迟更新、饱和策略由 Transformer Engine 一类层来管，底层仍可能调 Lt 或 cuDNN 的 FP8 计划。边界变成：数值协议在 TE，选核在 BLAS/DNN 库。只改存储类型为 FP8、计算仍 FP16，得到的是容量而不是 <a href="/llm/nvidia-gpu-gen">白皮书</a> 上的 FP8 峰值。cuDNN 的 FP8 注意力与 FA3 的 FP8 路径是不同实现，误差与形状甜点不同，不能共用一张表。</p><p>多 GPU 时，库边界停在单卡。All-Reduce 是 NCCL 的合同；把 TP 切开的小 GEMM 仍走 cuBLAS，但形状可能掉出启发式的舒适区。切分策略要同时看通信与 GEMM 效率，见 <a href="/llm/tensor-parallel">张量并行</a>。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>两套库能共享 Tensor Core，是因为最终都发射 MMA（或等价的卷积 MMA 变形）。差别在搜索空间与元数据。cuBLAS 假设规则步幅的二维/三维乘，描述符小，启发式快。cuDNN 要描述卷积的 pad/stride/dilation、注意力的因果掩码与序列长度、workspace 大小，计划空间大，第一次 <code>find</code> 可能很贵，因此推理引擎会缓存 cudnn 计划。CUDA Graph 捕获推理时，计划必须在捕获前固定，否则重放会打到错误的 workspace，见 <a href="/llm/cuda-graph-infer">CUDA Graph 捕获推理</a>。</p><p>Workspace 是另一条隐蔽边界。Lt 与 cuDNN 都可能要额外缓冲做 split-K 或算法 workspace。这部分算在「库的隐式显存」里，不出现在模型权重表上。服务进程按峰值 batch 预分配，避免捕获图之后再 <code>cudaMalloc</code>。</p>',6)),(t(),n(E,null,{default:e(()=>[c(r,{id:"mermaid-76",class:"mermaid",graph:"flowchart%20TD%0A%20%20I%5B%22%E8%BF%9B%E7%A8%8B%E5%90%AF%E5%8A%A8%EF%BC%9A%E5%BA%93%E5%88%9D%E5%A7%8B%E5%8C%96%22%5D%20--%3E%20F%5B%22%E9%A6%96%E6%AC%A1%20find%20%2F%20%E5%90%AF%E5%8F%91%E5%BC%8F%E9%80%89%E8%AE%A1%E5%88%92%22%5D%0A%20%20F%20--%3E%20WS%5B%22%E6%8C%89%E5%B3%B0%E5%80%BC%20batch%20%E9%A2%84%E5%88%86%E9%85%8D%20workspace%22%5D%0A%20%20WS%20--%3E%20CAP%5B%22CUDA%20Graph%20%E6%8D%95%E8%8E%B7%EF%BC%9A%E8%AE%A1%E5%88%92%E4%B8%8E%E6%8C%87%E9%92%88%E8%A2%AB%E9%92%89%E6%AD%BB%22%5D%0A%20%20CAP%20--%3E%20RP%5B%22%E9%87%8D%E6%94%BE%EF%BC%9A%E4%B8%8D%E5%86%8D%E9%80%89%E6%A0%B8%E3%80%81%E4%B8%8D%E5%86%8D%20cudaMalloc%22%5D%0A%20%20RP%20--%20%22%E4%B8%AD%E9%80%94%E6%8D%A2%E7%89%88%E6%9C%AC%E6%88%96%E7%BC%BA%E7%BC%93%E5%86%B2%22%20--%3E%20BAD%5B%22%E6%89%93%E5%88%B0%E9%94%99%E8%AF%AF%E8%AE%A1%E5%88%92%E6%88%96%E9%9A%90%E5%BC%8F%E5%88%86%E9%85%8D%EF%BC%9A%E5%BB%B6%E8%BF%9F%E6%8A%96%E5%8A%A8%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=o('<p><span class="marginnote">数字实例感受选核的分量：一层 \\(4096\\times4096\\) 的投影，\\(M=N=K=4096\\) 的 GEMM 约需 \\(2\\times4096^3\\approx1.4\\times10^{11}\\) 次乘加；若启发式选到只跑一半峰值的核，70 层模型的每一步都被拖慢同样的倍数。</span></p><p><span class="marginnote">同一 GEMM，cuBLAS 传统 API 与 Lt API 可能选出不同核。新代码应走 Lt；旧 <code>cublasGemmEx</code> 路径在部分形状上仍被框架保留。对照性能时写清调用的是哪套 API，以及是否允许 TF32。</span></p><h3 id="版本、tf32-与确定性" tabindex="-1">版本、TF32 与确定性 <a class="header-anchor" href="#版本、tf32-与确定性" aria-label="Permalink to &quot;版本、TF32 与确定性&quot;">​</a></h3><p>TF32 在 Ampere 上默认可能启用，训练与推理的尾差会变。确定性算法（<code>CUBLAS_WORKSPACE_CONFIG</code>、cuDNN deterministic 开关）通常放弃最快计划。生产若要对齐数值，应显式关 TF32 或钉算法；若要峰值，应接受启发式与版本漂移。这不是库的缺陷，是「最快」与「可复现」在同一 API 上的两个点。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要用 cuDNN 卷积去实现本可以是 GEMM 的线性层——描述符更重，计划空间更噪。不要用 cuBLAS 拼注意力还宣称已经解决 HBM 上的 \\(n\\times n\\)。不要把某次 <code>find</code> 在 A100 上选出的 ID 写进 H100 的启动参数。许可证上两套库随 CUDA toolkit / 驱动分发，版本要与驱动匹配；容器里「只升级框架不升级 libcudnn」是常见的静默回退来源。</p><p>CPU 回退、空形状、零 stride 的边角，库的错误码比手写核更规范，但也更不透明。服务侧应把 <code>CUBLAS_STATUS_*</code> / <code>CUDNN_STATUS_*</code> 打到日志，并保留当时的形状与对齐，否则无法复现启发式。</p><p><span class="marginnote">出处：cuBLAS / cuBLASLt 开发者指南（matmul 描述符、epilogue 限制、heuristic）；cuDNN 开发者指南（fusion engine、attention、workspace）；CUDA 编程指南与架构白皮书提供 MMA 精度与 TF32 语义。不引用未公开的选核代价模型。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>cuBLAS/Lt 的合同是 GEMM 与有限 epilogue；cuDNN 的合同是 DNN 层与更重的融合计划。</li><li>LLM 里线性走 Lt、融合注意力可能走 cuDNN 或 Flash 家族；不规则形状离开两套库。</li><li>启发式随版本、对齐、TF32 而变；要复现就必须钉版本或钉计划。</li><li>FP8 的数值协议常在 Transformer Engine，选核仍在这些库里。</li><li>Workspace 与计划缓存是推理捕获图之前必须冻结的状态。</li><li>出处：NVIDIA cuBLASLt 与 cuDNN 开发者指南。</li></ul>',10))])}const C=s(u,[["render",d]]);export{L as __pageData,C as default};
